local Text_Mail = readonly({
  Mail_100480_Desc = {
    Text = "Hüter, hast du gehört? Das abgelegene Kunstmuseum am Stadtrand wird bald schließen, und zwar an meinem Geburtstag. \n Dieses Museum ist ein Unikum in der Kunstwelt, zur Hälfte ein oberflächliches Experiment des Futurismus und zur Hälfte der Abfall von vor zwei Jahrhunderten. In seinem engen Bauch befinden sich nur seltsame Dinge, die in Auktionshäusern niemand anfassen würde: ein Porträt, das Schimpfwörter sagt, ein mechanischer Vogel, der niemals aufhört zu fliegen, ein Meeresrelief, das einem Übelkeit bereitet, Statuen, die aus Tränen gemacht sind, ein Geistermanuskript, das unaufhörlich schreibt, und ein menschlicher Schädelfragment, das beim Küssen Kinderlieder summt ... \n Es ist schwer, Ihnen zu beschreiben, wie sehr ich dieses Museum liebe! Vor fünfzig Jahren wurde es still und heimlich in dieser unbeachteten Ecke geboren. Heute, fünfzig Jahre später, stirbt es still in dieser Ecke. \n Seit meiner Kindheit haben mir die Leute gesagt, dass dieser Tag ein Fluch ist, genau wie ich. Ich glaube, das Schicksal war vielleicht schon im Voraus bestimmt, aber was soll's, wenn es so ist! Was dieses Museum geschaffen hat, ist eine einzigartige Welt, so viele verrückte Ideen sind in diesem kleinen Raum gestapelt, wie wunderbar das Bild! Seit dem Tag seiner Geburt hat es mit seinen Ausstellungsstücken kreiert. An diesem Tag seines Endes werden seine Vertrauten und alten Freunde ihm das letzte Geleit geben. \n Hüter, Sie haben in dem Link die Welt gesehen, wie ich sie sehe, und ich denke, Sie werden sich auch darauf freuen, mit mir dieses ungewöhnliche Museum zu besuchen, oder? \n\n Pickman"
  },
  Mail_100480_Name = {
    Text = "Die unbemerkte Ausstellungshalle"
  },
  Mail_100480_Sender = {Text = "Pickman"},
  Mail_116602_Desc = {
    Text = "Sehr geehrter Schutzherr:\nDas Ereignis „Die Nacht der Mitternachtssonne\" ist beendet. Die verbleibenden „Besuchsgeschenk\", „Bußopfer\" und „Loyalität Opferritual\" werden pro Stück im Verhältnis 1:40 gegen „Rosenskript\" umgetauscht. Bitte merken Sie sich den Erhalt."
  },
  Mail_116602_Name = {
    Text = "Geschenk-Rückgewinnung"
  },
  Mail_116602_Sender = {
    Text = "Verwaltungsrat der Missaga University"
  },
  Mail_117308_Desc = {
    Text = "Sehr geehrter Schutzherr:\n        Vielen Dank für Ihre Unterstützung und Anerkennung von [Vergessene Vorabend]. Um den Schutzherren an der Misaq Universität ein besseres Spielerlebnis zu bieten, laden wir Sie ein, die folgende Umfrage zur Erfahrung auszufüllen. Als Dank für Ihre Mitwirkung haben wir [Silber*200] als Belohnung vorbereitet, die Sie nach dem Ausfüllen der Umfrage erhalten können. Die Umfrage endet am 10. November um 9:00 Uhr, bitte denken Sie daran, rechtzeitig auszufüllen.\n        <SurveyLink:[Klicken Sie hier, um auszufüllen]>\n        Wir werden die Vorschläge jedes Schutzherrn ernsthaft anhören, Ihr Feedback wird dazu beitragen, dass die Misaq Universität immer besser wird!\n        —Möge der Silberne Schlüssel deinen Weg weisen."
  },
  Mail_117308_Name = {
    Text = "Versions-Erfahrungsumfrage V2.3.4"
  },
  Mail_117308_Sender = {
    Text = "Mythag Angelegenheiten Büro"
  },
  Mail_117309_Desc = {
    Text = "Sehr geehrter Schutzherr:\n        Vielen Dank für Ihre Unterstützung und Anerkennung von [Nacht der Vergessenheit]. Um den Schutzherren an der Misaq Universität ein besseres Spielerlebnis zu bieten, laden wir Sie ein, die folgende Umfrage zur Erfahrung auszufüllen. Als Dank für Ihre Mitarbeit haben wir [Silber*200] als Belohnung vorbereitet, die Sie nach Abschluss der Umfrage erhalten können. Die Umfrage endet am 30. März um 9:00 Uhr, bitte denken Sie daran, sie rechtzeitig auszufüllen.\n        <SurveyLink:[Klicken Sie hier, um auszufüllen]>\n        Wir werden die Vorschläge jedes Schutzherrn ernsthaft anhören, Ihr Feedback wird dazu beitragen, dass die Misaq Universität immer besser wird!\n        —Möge der Silberne Schlüssel deinen Weg weisen."
  },
  Mail_117309_Name = {
    Text = "Versions-Erfahrungsumfrage V2.4.3"
  },
  Mail_117309_Sender = {
    Text = "Mythag Angelegenheiten Büro"
  },
  Mail_120374_Desc = {
    Text = "Die zwei Jahre sind vergangen, Hüter des Geheimnisses. \n Wir haben uns am Rande des Endes gegenseitig bewacht. \n Du hast deine Gefühle und Erinnerungen in Wünsche verwandelt und das Licht der Hoffnung entfacht. \n Selbst wenn du von deinen ehemaligen Gefährten zwei Universen entfernt bist, hast du den Kampf gegen die Auflösung nie aufgegeben. \n Dich zu haben, ist unser Glück und auch das Glück dieser Welt. \n Nun hat dein Wunsch ein Wunder ausgelöst – Misaq existiert weiterhin und wird fortfahren. \n Halte weiterhin den Silberschlüssel fest, eines Tages kann er zum entscheidenden Verbindungspunkt werden, der zwei entfernte Welten verbindet. \n Wir werden unser Bestes tun, um die Möglichkeiten der Zukunft zu eröffnen und deinen Rückweg zu erleuchten."
  },
  Mail_120374_Name = {
    Text = "Der Moment des Wunders, das Licht der Heimkehr"
  },
  Mail_120374_Sender = {
    Text = "Misaq-Schulkatze·Light"
  },
  Mail_120909_Desc = {
    Text = "Sehr geehrter Schutzherr:\n        Mit dem Update V2.4.0 haben wir die Belohnungen für die “Quellflüssigkeit-Spende - Alumni-Spendenfonds“ erhöht. Für die Schutzherren, die die zusätzlichen Belohnungen vor dem Update bereits erhalten haben, werden wir die entsprechenden Belohnungen nachträglich zusenden. Bitte prüfen Sie den Erhalt."
  },
  Mail_120909_Name = {
    Text = "V2.4.0 Silberprimus-Spenden-Belohnungskompensation"
  },
  Mail_120909_Sender = {
    Text = "Mythag Angelegenheiten Büro"
  },
  Mail_121162_Desc = {
    Text = "Sehr geehrter Schutzherr:\n        In dem Update V2.4.0 haben wir die kostenlosen Belohnungen für “Abstiegsweg“, “Zeitreise“, “Sanatorium-Chronik“ und “Reise in die Stadt der Toten“ erhöht. Für die Schutzherren, die die kostenlosen Belohnungen vor dem Update bereits erhalten haben, werden wir die entsprechenden Belohnungen nachträglich auszahlen. Bitte überprüfe und nimm sie entgegen."
  },
  Mail_121162_Name = {
    Text = "V2.4.0 Reiseaufstiegsbelohnungskompensation"
  },
  Mail_121162_Sender = {
    Text = "Mythag Angelegenheiten Büro"
  },
  Mail_121373_Desc = {
    Text = "Schutzherr: \n\nAn diesem Tag war einst das größte Fest der Kirche. \nIch bin Seine Tochter und werde Ihn auferstehen lassen. \nDiese Menschen, einschließlich Miryam, feierten mit unbändiger Begeisterung und Tränen in den Augen, aber sie schauten auf mich, als ob ich nur eine leere Hülle wäre, die etwas trägt. \nIch habe nie Freude über das Kommen dieses Tages empfunden, denn jedes Mal, wenn er kommt, bedeutet es, dass ich der Angst ein Stück näher bin. \nIn dieser Angst hingegen empfinden andere höchste Freude über die Quelle der Furcht. Jetzt kann ich es zugeben, es lässt mich sowohl einsam als auch ängstlich fühlen. \nAber jetzt ist alles anders, vor meinem letzten Geburtstag habe ich das Schiff verlassen und bin in die wahre Welt gekommen... eine Welt ohne falsche Götter, mit dir an meiner Seite. \nAn diesem Geburtstag hoffe ich, dass jemand aufgrund meiner Geburt, und nicht aus einem anderen Grund, aufrichtig glücklich ist. \nWenn es du bist... nein, es muss unbedingt diese Person sein. \nHör gut zu, egal was passiert, die heutige Abendessenszeit muss mir gehören. \n\n“Murphy“"
  },
  Mail_121373_Name = {
    Text = "Es gibt dich..."
  },
  Mail_121373_Sender = {
    Text = "Murphy: Fauxgeboren"
  },
  Mail_121374_Desc = {
    Text = "Schutzherr: \n\nIch weiß nicht, was du für diesen besonderen Tag vorbereitet hast, egal wie extravagant und aufwendig, es ist offensichtlich, dass es angemessen ist. \nUnd aus der notwendigen Rücksichtnahme des Höhergestellten, falls du es “tatsächlich“ versäumt hast, meinen Geburtstag zu feiern – ich glaube nicht, dass eine solch absurde Situation eintreten wird. \nDieser Brief wird dir auch die letzte Chance geben, dich zu retten, bevor die Situation irreparabel wird. \nDie kostbaren Delikatessen aus Ozean und Land werden sicherlich von unbedeutenden Personen dargebracht, sie sind unwichtig. \nDie große Feier, die aufwendigen Rituale passen tatsächlich zu meiner Identität, aber heute, aus irgendeinem Grund, erscheinen sie etwas langweilig. \nDeshalb werde ich mir die Zeit nehmen, um dir die Ehre zu schenken, allein mit mir zu sein, als Belohnung dafür, dass du mich in dieses banale, kindische, aber so glückliche Leben gebracht hast, dass es mich zuvor neidisch machte. \nEin Gefolgsmann wird später die offizielle Einladung bringen, natürlich in einer Box im Wert von zwanzigtausend Leonian Florin. \nSei dankbar und denke an mich an jedem Jahr an diesem Tag. \n“Murphy“"
  },
  Mail_121374_Name = {
    Text = "Einladungsschreiben..."
  },
  Mail_121374_Sender = {
    Text = "Murphy: Fauxgeboren"
  },
  Mail_121651_Desc = {
    Text = "Sehr geehrter Hüter:\nIn der letzten Woche hast du im “Traumtauchen“ den Titel “{s1}“ erreicht.\nIn der letzten Woche hast du im “Vorgruppierungsmodus“ den Titel “{s2}“ erreicht, mit {s3} Siegen.\nIn der letzten Woche hast du im “Wahlmodus“ den Titel “{s4}“ erreicht, mit {s5} Siegen.\nBasierend auf diesen Ergebnissen erhältst du die folgenden zusätzlichen Belohnungen. Bitte vergiss nicht, sie abzuholen."
  },
  Mail_121651_Name = {
    Text = "Wöchentliche Rangbelohnungen für das Tiefgangsduell"
  },
  Mail_121651_Sender = {
    Text = "Verwaltungsrat der Missaga University"
  },
  Mail_121704_Desc = {
    Text = "Sehr geehrter Schutzherr: \nDas Ereignis „Fleischliche Begierden·Klone \" ist beendet. Die verbleibenden „Fertilitätssamenkern\" des Schutzherrn werden nun im Verhältnis von jeweils einem zu „Rosenskript*40 \" umgerechnet. Bitte prüfen Sie den Erhalt."
