  Mail_134024_Desc = {
    Text = "Lieber Schutzherr:\nDie „Tägliche Probe\" wurde entfernt. Die verbleibenden „Agentenbeweise\" werden zu einem Kurs von „Rosenskript\" × 10000 pro Beweis umgewandelt. Bitte denke daran, deine Belohnungen zu überprüfen."
