  },
  Mail_141470_Desc = {
    Text = "Geehrter Schutzherr:\n„Spiegelnder Gefangener·Klone\" ist Beendet. Die verbleibenden „Common Sense Buch\", „Mathematikbuch\" und „Literaturbuch\" des Schutzherrn werden im Verhältnis von je einem Stück zu „Rosenskript\" × 40 umgewandelt. Bitte denke daran, sie abzuholen."
