  Mail_145468_Desc = {
    Text = "Lieber Schutzherr,\nDas Event „Wenn alles wie gewohnt ist·Klone\" ist beendet. Die verbleibenden „Strandschalen\" wurden zum Kurs von „Rosenskript\" × 40 pro Einheit umgewandelt. Bitte denke daran, deine Belohnungen abzuholen."
