  Mail_148478_Desc = {
    Text = "Geehrter Schutzherr,\n        Die in der {s1}. Periode der „Semester-Aufgabe – Höhere Themen“ erhaltenen Belohnungen wurden noch nicht abgeholt. Diese werden Ihnen nun als Anhang per Post zugesandt. Bitte leeren Sie rechtzeitig Ihren Rucksack, bevor Sie die Belohnungen abholen."
