  Mail_148478_Name = {
    Text = "Nachlieferung nicht abgeholter Belohnungen der Höheren Themen – Periode {s1}"
  },
  Mail_148478_Sender = {
    Text = "Verwaltungsrat der Missaga University"
  },
  Mail_148514_Desc = {
    Text = "Geehrter Schutzherr,\n        Im Update der Version V1.4.3.5 haben wir in der „Abweichende Traumwelt: Verfluchung“ das Level „Neuer König“ hinzugefügt. Da einige Schutzherren nicht rechtzeitig über dieses Update informiert wurden, gingen sie irrtümlich davon aus, dass „Abweichende Traumwelt: Verfluchung“ vollständig abgeschlossen sei.\n        Daher haben wir im aktuellen Update der Version V2.6.2 für Schutzherren, die vor dem Update bereits die auf „Neuer König“ folgenden Level abgeschlossen hatten, den Abschlussfortschritt des Levels „Neuer König“ nachträglich ergänzt und die entsprechenden Erstabschluss-Belohnungen gleichzeitig nachgeliefert. Bitte überprüfen Sie Ihre Post."
  },
  Mail_148514_Name = {
    Text = "Fortschrittsergänzung für „Verfluchung“"
  },
  Mail_148514_Sender = {
    Text = "Verwaltungsrat der Missaga University"
  },
  Mail_148515_Desc = {
    Text = "Lieber Schutzherr:\n\nTa-da~ Überraschend, nicht wahr? Dies ist der erste Geburtstag dieser Fee in Misaq, und deshalb —\nAusgerechnet! Keine Werbemail, keine Einladung zum Gottesdienst, nicht einmal eine Prophezeiung vom Weltuntergang~\nDoch keine Sorge, diese Fee hat natürlich für die ganz besonderen Gläubigen etwas noch Wertvolleres und Besseres vorbereitet.\nAls allwissende und allmächtige Feenpatin kann man natürlich die selbstverständlichen Zweifel und Vorbehalte vorhersehen — auch wenn sie dieser Fee ein wenig Kummer bereiten. Doch um die Segnungen der Glaubensgemeinschaft zu verbreiten, sind kleine Opfergaben stets unvermeidlich.\nDaher: Denken Sie einen Moment nach und probieren Sie es einfach aus. Es gibt schließlich nichts zu verlieren — und was, wenn es wahr ist? Stimmt's?\nDies ist eine Gelegenheit, die nur einmal im Jahr vorkommt und unter keinen Umständen verpasst werden sollte~\nOhne jegliches Opfer, ohne jegliches Versprechen oder Tauschgeschäft — einzig und allein bei einem süßen Nachmittagstee mit der Feenpatin werden Sie erfahren, wie viele aufrichtige Gefühle für Sie unter dem Eis verborgen liegen.\nIst das nicht ein verlockendes Angebot?\nAnmerkung: Bitte bringen Sie unbedingt mindestens 10, 100, 1000 Leonian Florin zum Bezahlen mit — je mehr, desto besser.\n\nIn jenem Laden, den wir beide kennen, wartet auf Sie\nCaraboo"
  },
  Mail_148515_Name = {
    Text = "☆☆☆Super-Vorteilsmail☆☆☆"
  },
  Mail_148515_Sender = {Text = "Caraboo"},
  Mail_149949_Desc = {
    Text = "Dieser Brief hat zehntausend Mal die Reiche der Lebenden und der Toten durchquert. LÖSCH IHN NICHT!\n\nIn der Nacht des fünfzehnten Tages des siebten Monats öffnet sich das Geistertor weit, der kalte Wind erhebt sich, und die wandernden Seelen kehren heim.\nIch bin ███ aus Hu City im alten Kaiserreich Panlong – Yizhi Yè, Zhizha-Handwerker, Falter von Papiereffigieen und Brandopfern für die Toten, zu Euren Diensten!\n\nIm Auftrag des Zhongyuan-Geisterfestes, im Besitz des seelenbeschworenen Talismantextes, lege ich heute Nacht diesen Fluch auf Euch. Wer auch immer diese Worte erblickt: Eure Seele wird in das Register eingetragen, Euer Name ist bereits in das Buch geschrieben.\n\nUnd sollte dieser Brief nicht vor der Stunde des Zi, wenn die Nacht zur Mitternacht wird, an fünfzig Seelen der Lebenden weitergegeben werden, so werdet Ihr ganz gewiss –\n\n...Eure Dokumente werden einen Atemzug vor dem Speichern beschädigt...\n...Euer Bubble-Tea wird für immer drei Perlen zu wenig haben...\n...Euer Silberkern-Kommunikator wird für alle Ewigkeit bei 1% Akku verharren – ladet ihn, wie Ihr wollt, er wird sich niemals füllen...\n\nSeid ein braves Kind und tut, was man Euch sagt: Der Fluch löst sich von selbst, der Talisman verbrennt zu Asche, kein rachsüchtiger Geist wird Euch auf den Fersen folgen, und Eure Lebenslampe wird weiter und weiter brennen.\n\nLEITET ES WEITER!! JETZT SOFORT!!!"
  },
  Mail_149949_Name = {
    Text = "LÖSCH DIES, UND DU WIRST..."
  },
  Mail_149949_Sender = {Text = "Yizhi Yè"},
  Mail_149985_Desc = {
    Text = "Mein Gebieter,\n\nIch hoffe, dieser unerwartete Brief wirkt nicht anmaßend. Doch es gibt gewisse Gedanken, die ich nur Euch anvertrauen kann.\nLetzte Nacht hatte ich nach langer Zeit wieder einen Traum. Darin kehrte ich in mein Elternhaus zurück. Alles fühlte sich so vertraut an – die sanften, warmen Hände meines Vaters, die Volkslieder, die die Dienerin beim Kehren summte, und dieses weiße Pony, das mir gehörte... Ich hatte geglaubt, sie seien längst im Schlamm der Erinnerung versunken, doch als ich sie im Traum wiedersah, waren sie genauso warm wie eh und je.\nAls ich erwachte, sah ich, wie Misaqs Lehrer und Schüler draußen vor dem Fenster gemächlich plauderten – so friedlich und still, dass ich für einen Moment das Gefühl hatte, die Szene unterscheide sich nicht von jener in meinem Traum. Ich bemerkte auch, dass die unsichtbare Gegenwart, die mir anhaftet, seit heute Morgen ungewöhnlich ruhig war. Könnte es sein, dass man an seinem Geburtstag tatsächlich einem Glücksmoment begegnet?\nWenn dem so ist, darf ich mir heute vielleicht erlauben, ein wenig gierig zu sein......\nIch weiß, dass Menschen an ihren Geburtstagen oft Wünsche äußern, als Hoffnung für das kommende Jahr. Ich habe es längst aufgegeben, mir Geburtstagsw ünsche von jemandem zu erhoffen, doch es gibt eine Sache, die ich wirklich gerne die Chance hätte zu empfangen.\nSo wie Ihr mir Euer Vertrauen geschenkt habt, werde ich nichts vor Euch verbergen. Daher erlaubt mir, meinen Wunsch mit Euch zu teilen:\nWenn Ihr das nächste Mal eine Mission zu vergeben habt, ernennt mich bitte zu Eurem Eskortieren und lasst mich Euch begleiten.\nGanz gleich was geschieht, ich hoffe, dass ich immer dann, wenn Ihr Hilfe am dringendsten braucht, als Erster vor Euch stehe – um Euer beständigster Rollen-Schild zu sein.\nDas ist der Wunsch, den ich für dieses Jahr hege.\n\nOgier"
  },
  Mail_149985_Name = {
    Text = "Ein Geburtstagsw unsch…"
  },
  Mail_149985_Sender = {
    Text = "Ursprung: Ogier"
  },
  Mail_18019_Desc = {
    Text = "Lieber Hüter:\nDas System hat eine Rückerstattungsaktion auf dem aktuellen Konto festgestellt. Das Produktionsteam hat die virtuelle Währung, die Ihrer Rückerstattungsbestellung auf {s1} entspricht, abgezogen. Wenn der Kontostand nach dem Abzug einen negativen Wert anzeigt, muss er auf einen positiven Betrag wiederhergestellt werden, bevor eine normale Nutzung möglich ist.\nWenn Sie Fragen haben, wenden Sie sich bitte an den Kundenservice."
  },
