  },
  Mail_36867_Desc = {
    Text = "Lieber Hüter:\n        Im Update V1.2.4 hat sich die Menge der einzigartigen Materialien zum Upgrade von Fähigkeiten und der Mimetic Crystals, die von \"Transzendenter Existenz\" fallen, erhöht. Im Sinne der Fairness werden wir für Hüter, die die Belohnungen der \"Transzendenter Existenz\" in dieser Woche vor dem Update beansprucht haben, Mimetic Crystals im entsprechenden Wert der erhöhten Drops basierend auf dem empfohlenen Niveau der empfangenen Belohnungen ausgeben. Bitte überprüfen Sie Ihre Belohnungen."
  },
  Mail_36867_Name = {
