  Mail_43571_Sender = {
    Text = "Mythag Angelegenheiten Büro"
  },
  Mail_43821_Desc = {
    Text = "Lieber Hüter:\n        Im Update V1.3.0 haben die \"Missionsbericht\" Stufen 1/2/3/4/5/6 Belohnungen von Hüters Erfahrung 500/1000/1500/2000/2500/3000 hinzugefügt. Für Hüter, die die Belohnungen für die oben genannten Stufen vor dem Update bereits beansprucht hatten, stellen wir die entsprechende Erfahrung als Entschädigung aus. Bitte überprüfen Sie Ihre Belohnungen."
