  Mail_43821_Sender = {
    Text = "Mythag Angelegenheiten Büro"
  },
  Mail_44571_Desc = {
    Text = "Sehr geehrter Hüter:\nDer [Seelenhirt] endet am 18. April um 9:00 Uhr[GMT+8]. Nach dem Ende der Veranstaltung werden die entsprechenden Eingänge geschlossen, einschließlich der Straßen zur Kirche und des Marktes der Kirche. Unbenutzte Marktmarken verschwinden automatisch. Hüter, erinnern Sie sich daran, vor dem Ende der Veranstaltung rechtzeitig im Markt der Kirche einzukaufen"
  },
  Mail_44571_Name = {
    Text = "Das Soul Shepherd-Event neigt sich dem Ende zu"
  },
  Mail_44571_Sender = {
    Text = "Verwaltungsrat der Missaga University"
  },
  Mail_44690_Desc = {
    Text = "Hallo, Hüter:\nDu hast während des phantasmatischen Tauchgangs gestern mit dem Untersuchungstitel \"{s1}\" Feldarbeit geleistet. Nachfolgend sind deine Rangbelohnungen aufgeführt; bitte vergiss nicht, sie abzuholen."
