  },
  Mail_44843_Sender = {
    Text = "Mythag Angelegenheiten Büro"
  },
  Mail_47305_Desc = {
    Text = "Lieber Hüter:\nIn dem gestrigen Phantasma-Tauchgang haben Sie die höchste Schwierigkeit erreicht: \"{s1}\".\nIn der gestrigen Traphase haben Sie den Titel \"{s2}\" verdient, jedoch keine Siege in den Matches errungen.\nBasierend auf diesen Herausforderungsresultaten erhalten Sie die folgenden D-Juwel-Belohnungen. Bitte denken Sie daran, diese zu überprüfen."
