  Mail_47308_Desc = {
    Text = "Lieber Hüter:\nIn dem gestrigen Phantasma-Tauchgang haben Sie die höchste Schwierigkeit erreicht: \"{s1}\".\nIn der gestrigen Traphase haben Sie den Titel \"{s2}\" verdient und Siege erzielt.\nBasierend auf diesen Herausforderungsresultaten erhalten Sie die folgenden D-Juwel-Belohnungen. Bitte denken Sie daran, diese zu überprüfen."
  },
  Mail_47308_Name = {
    Text = "Belohnung für das Schach-D-Jewel beim tiefen Eintauchen"
  },
  Mail_47308_Sender = {
    Text = "Verwaltungsrat der Missaga University"
  },
  Mail_48005_Desc = {
    Text = "Lieber Hüter:\n\nIch entschuldige mich, dass ich dich störe, und hoffe, dass meine schreckliche Handschrift deine gute Laune nicht ruiniert – ich bin wirklich nicht gut im Schreiben...\nIch schreibe diesen Brief, um dir zu sagen, dass mein Geburtstag anscheinend angekommen ist. Ich habe ein paar kleine Kekse für den Anlass gebacken, und ich hoffe, du wirst sie probieren.\nUm ehrlich zu sein, bin ich mir nicht sicher, ob dieses Datum richtig ist. Seit ich mit der Auflösung infiziert bin, verblassen die Spuren meines Daseins Stück für Stück.\nMiss Puppe hat mich einmal gefragt, wie es sich anfühlt, zuzusehen, wie ich von allen vergessen werde.\nEs ist schwer zu beschreiben... Es ist, als stünde man im pechschwarzen Dunkel am Rand eines leuchtenden Flusses. Auf der anderen Seite reden die Menschen, beschäftigt mit ihren eigenen Angelegenheiten, und gehen an mir vorbei, während ich nur zuschauen kann, ohne ein Geräusch von mir geben zu können.\nEs ist ein einsames Gefühl. Glücklicherweise bist du nicht unter diesen Menschen.\nZumindest erinnerst du dich an meine Geschichte, nicht wahr?\n\nP.S., zwölf kleine Kekse sind diesem Brief beigefügt.\n\nMason"
  },
  Mail_48005_Name = {
    Text = "Es tut mir leid, zu stören..."
  },
  Mail_48005_Sender = {Text = "“24“"},
  Mail_48145_Desc = {
    Text = "Lieber Hüter:\nDas Event \"Mehrfache Heilung\" ist beendet. Wir werden die verbleibende Eventwährung \"Erinnerungsrätsel\" gemäß dem unbegrenzten Umrechnungskurs von \"Persönlichkeitsanalyse\" zurückholen. Bitte denken Sie daran, Ihre Belohnungen zu überprüfen."
  },
  Mail_48145_Name = {
    Text = "Erinnerungsrätselwiederherstellung"
  },
  Mail_48145_Sender = {
