  Mail_49931_Desc = {
    Text = "Sehr geehrter Schutzherr: \n Das Ereignis „Fleischliche Begierden\" ist beendet. Die verbleibenden „Fertilitätssamenkern\" des Schutzherrn werden nun im Verhältnis von jeweils einem zu „Rosenskript\" × 20 umgerechnet. Bitte merken Sie sich den Erhalt."
