  Mail_49931_Name = {
    Text = "Die Mutter-Saat-Rückgewinnung"
  },
  Mail_49931_Sender = {
    Text = "Verwaltungsrat der Missaga University"
  },
  Mail_50344_Desc = {
    Text = "Kleiner Setzling:\n\nDer Wind trägt deinen Duft – er ist süßer als bei unserer ersten Begegnung.\nDu bist in meiner Liebe gewachsen, zur Reife genährt... wie Bienen und Honig.\nHeute ist ein besonderer Tag. Kommst du mich besuchen?\nIch habe geduldig lange gewartet, so wie du es erbeten hast... Ist es nicht Zeit für eine kleine Belohnung?\n\nThais"
  },
  Mail_50344_Name = {
    Text = "Süß wie Honig..."
  },
  Mail_50344_Sender = {Text = "Thais"},
  Mail_51376_Desc = {
    Text = "Sehr geehrter Schutzherr: \nDas „Magie der Story \"-Ereignis ist beendet. Übriggebliebene „Wandernde Inspiration\" wird pro Stück im Verhältnis 1:60 gegen „Rosenskript \" eingetauscht. Bitte überprüfen Sie Ihr Inventar."
