  Mail_55168_Desc = {
    Text = "Sehr geehrter Hüter:\nDas „Verwelken im Frühling\"-Ereignis ist beendet. Übriggebliebene „Fröhliches Gedicht\", „melancholische Poesie\" und „Poem des Bedauerns\" werden pro 200 Stück im Verhältnis 1:5000 gegen „Rosenskript\" umgetauscht. Bitte überprüfen Sie Ihr Inventar."
