  Mail_61155_Desc = {
    Text = "Sehr geehrter Schutzherr: \n Das „Mehrfachheilung·Klone\"-Ereignis ist beendet. Die verbleibenden Eventwährungen „Erinnerungspuzzleteile\" werden pro Stück im Verhältnis 1:40 gegen „Rosenskript\" umgetauscht. Bitte überprüfen Sie Ihr Inventar."
