  Mail_65442_Desc = {
    Text = "Sehr geehrter Schutzherr:\nDas „Wandeltür\"-Ereignis ist beendet. Die verbleibenden Eventwährungen „Endzeiger\" werden pro Stück im Verhältnis 1:40 gegen „Rosenskript\" umgetauscht. Bitte überprüfen Sie Ihr Inventar."
