  Mail_79646_Desc = {
    Text = "Sehr geehrter Schutzherr,\nDie Veranstaltung „Verborgen unter der Erinnerung„ ist beendet. Ihre verbleibenden Diagnoseberichte werden im Verhältnis von je Rosenskript*40 umgetauscht. Bitte überprüfen Sie Ihren Erhalt, Schutzherr."
