  Mail_90000_Desc = {
    Text = "Sehr geehrter Hüter: \n Aufgrund deiner hervorragenden Leistung in „Schatten, die das göttliche Reich begehren: Unruhe in den Gezeiten“ wirst du die folgenden Belohnungen erhalten. Bitte vergiss nicht, sie abzuholen.\n\n"
