  },
  Mail_90015_Desc = {
    Text = "Sehr geehrter Schutzherr:\nDie 1, 5-jährige Jubiläumsveranstaltung ist beendet. Die verbleibenden „Einfacher Phantasiekleidervoucher(Phase 1)\" werden im Verhältnis 1:1 gegen „Einladung des Unstofflichen\" umgetauscht. Bitte prüfen Sie, ob Sie die Belohnung erhalten haben."
