  },
  Mail_90231_Desc = {
    Text = "Sehr geehrter Schutzherr:\nDas „Spiegelnder Gefangener\"-Ereignis ist beendet. Übriggebliebene „Common Sense Buch\", „Mathematikbuch\" und „Literaturbuch\" werden pro Stück im Verhältnis 1:40 gegen „Rosenskript\" umgetauscht. Bitte merken Sie sich den Erhalt."
